const ARIAL = { ' ': 278, '.': 278, 0: 556, 1: 556, 5: 556, 9: 556, A: 667, C: 722, E: 667, L: 556, N: 722, O: 778, R: 722, S: 667, T: 611, W: 944, Y: 667, '•': 350 };
// A line printed on the label along a circle of radius R about (cx, cy), hanging under the
// centre; wrapR is the can radius, so glyphs narrow towards the edges.
function arcText(str, cx, cy, R, size, fill, wrapR) {
  const adv = [...str].map(ch => ARIAL[ch] * size / 1000);
  let at = -adv.reduce((a, b) => a + b, 0) / 2, out = '';
  [...str].forEach((ch, i) => {
    const mid = at + adv[i] / 2; at += adv[i];
    if (ch === ' ') return;
    const th = mid / R, y = r2(cy + R * Math.cos(th));
    const u = R * Math.sin(th) / wrapR, c = Math.cos(u), x = r2(cx + wrapR * Math.sin(u));
    out += text(0, 0, ch, size, fill, `transform="translate(${x} ${y}) rotate(${r2(Math.atan2(Math.sin(-th), Math.cos(-th) * c) * 180 / Math.PI)}) scale(${r2(c)} 1)"`);
  });
  return out;
}
const onCan = u => r2(100 + 45 * Math.sin(Math.max(-1.5707, Math.min(1.5707, u / 45))));
